// The browser runtime must reproduce the Python server: same token ids, same model outputs.
// The fixture is generated by the backend's own AuraSense class (see docs/DEVELOPMENT.md).
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'
import * as ort from 'onnxruntime-web'

const root = new URL('../public/models/aura-sense/', import.meta.url)
const fixture = JSON.parse(readFileSync(new URL('./fixtures/sense_fixture.json', import.meta.url), 'utf8'))
const tokJson = JSON.parse(readFileSync(new URL('tokenizer.json', root), 'utf8'))

// core.js imports a JSON lexicon through Vite; load just the tokenizer section without Vite.
const src = readFileSync(new URL('../src/engine/core.js', import.meta.url), 'utf8')
const start = src.indexOf('const isPunct')
const end = src.indexOf('// ---------------------------------------------------------------- Aura-Sense')
const { WordPiece } = await import(`data:text/javascript,${encodeURIComponent(src.slice(start, end))}`)

test('tokenizer matches the Python tokenizer exactly', () => {
  const wp = new WordPiece(tokJson)
  for (const f of fixture) assert.deepEqual(wp.encode(f.text, 128), f.ids, f.text)
})

test('onnxruntime-web reproduces the server outputs', async () => {
  ort.env.wasm.numThreads = 1
  const session = await ort.InferenceSession.create(readFileSync(new URL('model.onnx', root)))
  for (const f of fixture) {
    const n = f.ids.length
    const out = await session.run({
      input_ids: new ort.Tensor('int64', BigInt64Array.from(f.ids, BigInt), [1, n]),
      attention_mask: new ort.Tensor('int64', new BigInt64Array(n).fill(1n), [1, n]),
    })
    const [a, b] = out.risk_logits.data
    const risk = Math.exp(b) / (Math.exp(a) + Math.exp(b))
    assert.ok(Math.abs(risk - f.risk) < 1e-3, `risk ${risk} vs ${f.risk} for "${f.text}"`)
    assert.ok(Math.abs(out.va.data[0] - f.valence) < 1e-3, `valence for "${f.text}"`)
    for (let i = 0; i < 8; i++) assert.ok(Math.abs(out.embedding.data[i] - f.embedding8[i]) < 1e-3)
  }
})
